/* ── the kolam engine ──
   Dots on a square grid. The line runs diagonally between them, crosses where two dots sit side by side,
   and turns around the outside dots, so every dot ends up inside a loop. Separate loops are joined into one line. */
function loopsOf(cells, mirrors){
  const has = (x, y) => cells.has(x + "," + y), seen = new Set(), loops = [];
  for (const key of cells) {
    const [cx, cy] = key.split(",").map(Number);
    for (const q of [[1, 1], [-1, 1], [-1, -1], [1, -1]]) {
      if (seen.has(cx + "," + cy + "," + q)) continue;
      let P = [2 * cx + q[0], 2 * cy], d = [-q[0], q[1]];
      const P0 = P.slice(), d0 = d.slice(), loop = [];
      for (let g = 0; g < 4000; g++) {
        const N = [P[0] + d[0], P[1] + d[1]];
        const C = (N[0] % 2 === 0 && P[1] % 2 === 0) ? [N[0], P[1]] : [P[0], N[1]];
        const qq = [Math.sign((P[0] + N[0]) / 2 - C[0]), Math.sign((P[1] + N[1]) / 2 - C[1])];
        seen.add(C[0] / 2 + "," + C[1] / 2 + "," + qq);
        let kind, ek;
        if (Math.abs(N[0] % 2) === 1) {
          const ax = C[0] / 2 + d[0], ay = C[1] / 2; ek = "v" + Math.min(C[0] / 2, ax) + "," + ay;
          if (has(ax, ay) && !mirrors.has(ek)) kind = "x"; else { kind = has(ax, ay) ? "m" : "b"; d = [-d[0], d[1]]; }
        } else {
          const ax = C[0] / 2, ay = C[1] / 2 + d[1]; ek = "h" + ax + "," + Math.min(C[1] / 2, ay);
          if (has(ax, ay) && !mirrors.has(ek)) kind = "x"; else { kind = has(ax, ay) ? "m" : "b"; d = [d[0], -d[1]]; }
        }
        loop.push({ c: C, q: qq, n: N, kind, ek });
        P = N;
        if (P[0] === P0[0] && P[1] === P0[1] && d[0] === d0[0] && d[1] === d0[1]) break;
      }
      loops.push(loop);
    }
  }
  return loops;
}
function kolamOf(cells){
  const mirrors = new Set(); let loops = loopsOf(cells, mirrors);
  if (!cells.size) return [];
  let mx = 0, my = 0; cells.forEach(k => { const [x, y] = k.split(",").map(Number); mx += x; my += y; }); mx /= cells.size; my /= cells.size;
  for (let pass = 0; pass < 80 && loops.length > 1; pass++) {
    const owner = new Map();
    loops.forEach((l, i) => l.forEach(s => { if (s.kind === "x") { const a = owner.get(s.ek) || new Set(); a.add(i); owner.set(s.ek, a); } }));
    let best = null, bd = 1e9;
    owner.forEach((set, ek) => {
      if (set.size < 2) return;
      const m = ek.slice(1).split(",").map(Number), ex = m[0] + (ek[0] === "v" ? .5 : 0), ey = m[1] + (ek[0] === "h" ? .5 : 0);
      const dd = Math.hypot(ex - mx, ey - my) + (ek[0] === "v" ? 0 : .001) - ex * 1e-4;
      if (dd < bd) { bd = dd; best = ek; }
    });
