      if (s.kind === "x") pts.push(s.n);
      else { const o = s.kind === "b" ? OUT : IN; pts.push([s.n[0] + (s.n[0] - s.c[0]) * o, s.n[1] + (s.n[1] - s.c[1]) * o]); }
    });
