let bits = [], fxRun = false, fxLast = 0, atlasOk = false;
atlas.onload = () => { atlasOk = true; };
function sizeCv(){ const d = Math.min(2, devicePixelRatio || 1); cv.width = innerWidth * d; cv.height = innerHeight * d; cx.setTransform(d, 0, 0, d, 0, 0); }
sizeCv(); addEventListener("resize", sizeCv);
function bit(x, y, vx, vy){ return { x, y, vx, vy, k: SPR[Math.floor(Math.random() * SPR.length)], r: Math.random() * 6.3, vr: (Math.random() - .5) * 6, s: .32 + Math.random() * .22, ph: Math.random() * 6.3 }; }
function burst(x, y, n, power){ if (calm) return; if (!atlas.src) atlas.src = A + "petals.webp"; for (let i = 0; i < n; i++) { const a = -Math.PI / 2 + (Math.random() - .5) * 2.6, s = power * (.35 + Math.random() * .75); bits.push(bit(x, y, Math.cos(a) * s, Math.sin(a) * s)); } start(); }
function start(){ if (bits.length > 400) bits.splice(0, bits.length - 400); if (!fxRun) { fxRun = true; fxLast = performance.now(); requestAnimationFrame(step); } }
function step(t){
  const dt = Math.min(.033, (t - fxLast) / 1000); fxLast = t;
  cx.clearRect(0, 0, innerWidth, innerHeight);
  bits = bits.filter(b => b.y < innerHeight + 40);
  for (const b of bits) {
    b.vy = Math.min(b.vy + 460 * dt, 140); b.vx *= .985;
    b.x += (b.vx + Math.sin(t / 420 + b.ph) * 28) * dt; b.y += b.vy * dt; b.r += b.vr * dt;
